<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from "vue";
import { useRouter } from "vue-router";
import { BookOpen, CheckCircle2, ChevronLeft, ChevronRight, Image as ImageIcon, Plus, Search, Trash2, X } from "lucide-vue-next";
import categories from "../../config/article-categories.json";
import dailyCarePreview from "../../assets/banners/daily-care.webp";
import prescriptionCarePreview from "../../assets/banners/prescription-care.webp";
import { deleteArticle, deleteArticles, deleteBanner, getAdminArticlesPage, getBanners, saveBanner, uploadFile } from "./api";
import ImageCropper from "./ImageCropper.vue";

const articles = ref<any[]>([]); const banners = ref<any[]>([]); const tab = ref<"articles" | "banners">("articles"); const query = ref(""); const status = ref("all"); const pageSize = ref(10); const articlePage = ref(1); const articleTotal = ref(0); const selectedArticleIds = ref<string[]>([]); const loading = ref(false); const notice = ref("");
const router = useRouter();
const bannerDialog = ref(false); const cropDialog = ref(false); const cropImage = ref(""); const cropName = ref(""); const uploadingImage = ref(false);
const dragActive = ref(false);
const cropStage = ref<HTMLElement | null>(null); const cropSource = ref<HTMLImageElement | null>(null); const cropNatural = ref({ width: 0, height: 0 }); const cropViewport = ref({ left: 0, top: 0, width: 0, height: 0, scale: 1 });
const cropSelection = ref({ x: 0, y: 0, width: 0, height: 0 });
const cropDrag = ref<{ mode: "move" | "nw" | "ne" | "sw" | "se"; startX: number; startY: number; selection: typeof cropSelection.value } | null>(null);
const bannerForm = ref<any>({ id: "", title: "", imageKey: "", target: "/pages/shop/list", active: true, mode: "default", sort: 0 });
const defaultBanners = [{ title: "秋季轻养计划", imageKey: "/assets/banners/daily-care.webp", preview: dailyCarePreview, target: "/pages/shop/list" }, { title: "处方饮片服务", imageKey: "/assets/banners/prescription-care.webp", preview: prescriptionCarePreview, target: "/pages/prescriptions/list" }];
const legacyCategoryMap: Record<string, string> = { 健康科普: "daily-health", 用药指引: "prescription-guide", 生活方式: "daily-health" };
const categoryName = (value: string) => categories.find((category) => category.key === value)?.name || legacyCategoryMap[value] || value || "未分类";
const targetName = (value: string) => ({ "/pages/shop/list": "商城首页", "/pages/prescriptions/list": "处方服务", "/pages/index/index": "小程序首页" } as Record<string, string>)[value] || (value ? "商品详情" : "未设置");
const bannerImage = (row: any) => defaultBanners.find((item) => item.imageKey === row.imageKey)?.preview || row.imageKey;

const filteredArticles = computed(() => articles.value);
const articleTotalPages = computed(() => Math.max(1, Math.ceil(articleTotal.value / pageSize.value)));
const allVisibleSelected = computed(() => filteredArticles.value.length > 0 && filteredArticles.value.every((row) => selectedArticleIds.value.includes(row.id)));
const selectedCount = computed(() => selectedArticleIds.value.length);
const cropViewportStyle = computed(() => ({ left: `${cropViewport.value.left}px`, top: `${cropViewport.value.top}px`, width: `${cropViewport.value.width}px`, height: `${cropViewport.value.height}px` }));
const cropImageStyle = computed(() => cropViewportStyle.value);
const cropSelectionStyle = computed(() => ({ left: `${cropSelection.value.x * cropViewport.value.scale}px`, top: `${cropSelection.value.y * cropViewport.value.scale}px`, width: `${cropSelection.value.width * cropViewport.value.scale}px`, height: `${cropSelection.value.height * cropViewport.value.scale}px` }));
const cropMaskStyle = computed(() => {
  const selection = cropSelection.value; const scale = cropViewport.value.scale; const width = cropViewport.value.width; const height = cropViewport.value.height;
  const left = selection.x * scale; const top = selection.y * scale; const right = width - (selection.x + selection.width) * scale; const bottom = height - (selection.y + selection.height) * scale;
  return { top: { left: "0", top: "0", width: "100%", height: `${Math.max(0, top)}px` }, bottom: { left: "0", bottom: "0", width: "100%", height: `${Math.max(0, bottom)}px` }, left: { left: "0", top: `${top}px`, width: `${Math.max(0, left)}px`, height: `${selection.height * scale}px` }, right: { right: "0", top: `${top}px`, width: `${Math.max(0, right)}px`, height: `${selection.height * scale}px` } };
});
const filteredBanners = computed(() => banners.value.filter((row) => !query.value || `${row.title} ${row.target}`.toLowerCase().includes(query.value.toLowerCase())));
function toast(message: string) { notice.value = message; window.setTimeout(() => { notice.value = ""; }, 2500); }
async function loadArticles(page = articlePage.value) { try { const result = await getAdminArticlesPage({ keyword: query.value, published: status.value === "all" ? undefined : status.value === "published" ? "true" : "false", page, pageSize: pageSize.value }); articles.value = result.items || []; articlePage.value = result.page || page; articleTotal.value = Number(result.total || 0); selectedArticleIds.value = []; } catch { toast("文章数据加载失败，请检查服务端"); } }
function normalizePageSize() { const value = Number(pageSize.value); if (!Number.isInteger(value) || value < 1) pageSize.value = 10; else if (value > 200) pageSize.value = 200; }
async function load() { loading.value = true; try { await Promise.all([loadArticles(1), getBanners().then((items) => { banners.value = items; })]); } catch { toast("内容数据加载失败，请检查服务端"); } finally { loading.value = false; } }
onMounted(load);
let searchTimer: number | undefined;
watch([query, status, pageSize], () => { if (searchTimer) window.clearTimeout(searchTimer); searchTimer = window.setTimeout(() => loadArticles(1), 300); });
function openArticle(row?: any) { router.push(row?.id ? `/content/articles/${encodeURIComponent(String(row.id))}/edit` : "/content/articles/new"); }
function openBanner(row?: any) { const first = defaultBanners[0]; bannerForm.value = row ? { ...row, mode: row.mode || "custom", sort: Number(row.sort || 0) } : { id: "", title: first.title, imageKey: first.imageKey, target: first.target, active: true, mode: "default", sort: 0 }; bannerDialog.value = true; }
async function removeArticle(row: any) { if (!window.confirm("确定删除这篇文章吗？")) return; try { await deleteArticle(row.id); toast("文章已删除"); await loadArticles(articlePage.value); } catch { toast("文章删除失败"); } }
function toggleArticle(id: string) { selectedArticleIds.value = selectedArticleIds.value.includes(id) ? selectedArticleIds.value.filter((item) => item !== id) : [...selectedArticleIds.value, id]; }
function toggleAllArticles() { selectedArticleIds.value = allVisibleSelected.value ? [] : filteredArticles.value.map((row) => row.id); }
async function batchDeleteArticles() { if (!selectedArticleIds.value.length) return toast("请先选择文章"); if (!window.confirm(`确定删除选中的 ${selectedArticleIds.value.length} 篇文章吗？`)) return; try { await deleteArticles(selectedArticleIds.value); selectedArticleIds.value = []; toast("选中文章已删除"); await loadArticles(Math.min(articlePage.value, articleTotalPages.value)); } catch { toast("批量删除失败"); } }
async function saveBannerForm() { if (!bannerForm.value.title || !bannerForm.value.imageKey) return toast("请完善轮播标题和图片"); try { await saveBanner(bannerForm.value); bannerDialog.value = false; toast("轮播已保存"); await load(); } catch { toast("轮播保存失败"); } }
async function removeBanner(row: any) { if (!window.confirm("确定删除这张轮播图吗？")) return; try { await deleteBanner(row.id); toast("轮播已删除"); await load(); } catch { toast("轮播删除失败"); } }
function chooseDefault(event: Event) { const index = Number((event.target as HTMLSelectElement).value); const item = defaultBanners[index]; if (!item) return; bannerForm.value = { ...bannerForm.value, mode: "default", title: item.title, imageKey: item.imageKey, target: item.target }; }
function selectDefault(index: number) { const item = defaultBanners[index]; if (!item) return; bannerForm.value = { ...bannerForm.value, mode: "default", title: item.title, imageKey: item.imageKey, target: item.target }; }
function processImageFile(file?: File) { if (!file) return; if (!file.type.startsWith("image/")) return toast("请选择图片文件"); if (file.size > 8 * 1024 * 1024) return toast("图片不能超过 8MB"); cropName.value = file.name; const reader = new FileReader(); reader.onload = () => { cropImage.value = String(reader.result || ""); cropDialog.value = true; }; reader.readAsDataURL(file); }
function chooseFile(event: Event) { processImageFile((event.target as HTMLInputElement).files?.[0]); }
function dragOver(event: DragEvent) { event.preventDefault(); dragActive.value = true; }
function dragLeave(event: DragEvent) { event.preventDefault(); dragActive.value = false; }
function dropFile(event: DragEvent) { event.preventDefault(); dragActive.value = false; processImageFile(event.dataTransfer?.files?.[0]); }
async function handleBannerCrop(file: File) { uploadingImage.value = true; try { const result = await uploadFile(file, "banner"); bannerForm.value.imageKey = result.fileKey; bannerForm.value.mode = "custom"; cropDialog.value = false; toast("图片已裁剪并上传"); } catch (error: any) { toast(error?.message || "轮播图上传失败"); } finally { uploadingImage.value = false; } }
onMounted(() => undefined); onUnmounted(() => { if (searchTimer) window.clearTimeout(searchTimer); });
</script>

<template>
  <div class="content-manager">
    <div v-if="notice" class="content-toast">{{ notice }}</div>
    <header class="content-manager-head"><div><p class="panel-kicker">内容管理</p><h2>科普文章与首页轮播</h2><p>保存后会同步到小程序首页、科普列表和文章详情。</p></div><div class="content-manager-actions"><button class="ghost-button" @click="load">{{ loading ? "加载中" : "刷新" }}</button><button class="primary-small" @click="tab === 'articles' ? openArticle() : openBanner()"><Plus :size="15" />{{ tab === 'articles' ? '新增文章' : '新增轮播' }}</button></div></header>
    <div class="content-tabs"><button :class="{ active: tab === 'articles' }" @click="tab = 'articles'">科普文章</button><button :class="{ active: tab === 'banners' }" @click="tab = 'banners'">首页轮播</button></div>
    <div class="content-toolbar"><div class="toolbar-search"><Search :size="15" /><input v-model="query" placeholder="搜索标题、标签或目标" /></div><select v-if="tab === 'articles'" v-model="status" class="filter-select"><option value="all">全部文章</option><option value="published">已发布</option><option value="draft">草稿</option></select><label v-if="tab === 'articles'" class="page-size-control">每页 <input v-model.number="pageSize" type="number" min="1" max="200" step="1" @change="normalizePageSize" /> 条</label><button v-if="tab === 'articles' && selectedCount" class="danger-small" type="button" @click="batchDeleteArticles">批量删除（{{ selectedCount }}）</button><span class="content-count">{{ tab === 'articles' ? articleTotal : filteredBanners.length }} 条记录</span></div>

    <section v-if="tab === 'articles'" class="content-list"><div class="article-list-toolbar"><label class="select-all-row"><input type="checkbox" :checked="allVisibleSelected" :disabled="!filteredArticles.length" @change="toggleAllArticles" />选择当前页</label><span v-if="selectedCount" class="selected-count">已选择 {{ selectedCount }} 篇</span></div><div v-for="row in filteredArticles" :key="row.id" class="content-row"><input class="article-row-check" type="checkbox" :checked="selectedArticleIds.includes(row.id)" @change="toggleArticle(row.id)" /><div class="content-icon"><BookOpen :size="18" /></div><div class="content-copy"><b>{{ row.title }}</b><small>{{ categoryName(row.category || row.tag) }} · {{ row.summary || '暂无摘要' }}</small></div><em class="status-pill" :class="row.published === false ? 'slate' : 'teal'">{{ row.published === false ? '草稿' : '已发布' }}</em><em v-if="row.recommended" class="recommend-pill">推荐</em><button class="row-action" @click="openArticle(row)">编辑 <ChevronRight :size="13" /></button><button class="icon-danger" title="删除文章" @click="removeArticle(row)"><Trash2 :size="15" /></button></div><div v-if="!filteredArticles.length" class="content-empty">没有匹配文章，点击“新增文章”开始录入。</div><div class="content-pagination"><span>第 {{ articlePage }} / {{ articleTotalPages }} 页</span><div><button class="icon-button" type="button" :disabled="articlePage <= 1" title="上一页" @click="loadArticles(articlePage - 1)"><ChevronLeft :size="16" /></button><button class="icon-button" type="button" :disabled="articlePage >= articleTotalPages" title="下一页" @click="loadArticles(articlePage + 1)"><ChevronRight :size="16" /></button></div></div></section>
    <section v-else class="content-list"><div v-for="row in filteredBanners" :key="row.id" class="banner-row"><div class="banner-preview"><img :src="bannerImage(row)" alt="" /></div><div class="content-copy"><b>{{ row.title }}</b><small>{{ row.mode === 'default' ? '默认图片' : '自定义图片' }} · 点击进入{{ targetName(row.target) }} · 排序 {{ row.sort || 0 }}</small></div><em class="status-pill" :class="row.active === false ? 'slate' : 'teal'">{{ row.active === false ? '停用' : '启用' }}</em><button class="row-action" @click="openBanner(row)">编辑 <ChevronRight :size="13" /></button><button class="icon-danger" title="删除轮播" @click="removeBanner(row)"><Trash2 :size="15" /></button></div><div v-if="!filteredBanners.length" class="content-empty">没有轮播图，点击“新增轮播”开始配置。</div></section>


    <div v-if="bannerDialog" class="dialog-backdrop" @click.self="bannerDialog = false"><form class="dialog-card content-dialog" @submit.prevent="saveBannerForm"><div class="dialog-head"><div><p class="panel-kicker">轮播设置</p><h2>{{ bannerForm.id ? '编辑首页轮播' : '新增首页轮播' }}</h2></div><button type="button" class="icon-button" @click="bannerDialog = false"><X :size="16" /></button></div><label>图片来源<select v-model="bannerForm.mode" @change="bannerForm.mode === 'default' && selectDefault(0)"><option value="default">使用系统默认图片</option><option value="custom">上传自定义图片</option></select></label><div v-if="bannerForm.mode === 'default'" class="default-banner-options"><label v-for="(item, index) in defaultBanners" :key="item.imageKey" class="default-banner-option"><input type="radio" name="default-banner" :checked="bannerForm.imageKey === item.imageKey" @change="selectDefault(index)" /><img :src="item.preview" alt="" /><span>{{ item.title }}</span></label></div><label v-else class="custom-image-field upload-drop-zone" :class="{ 'is-dragging': dragActive }" @dragover="dragOver" @dragleave="dragLeave" @drop="dropFile"><span class="upload-drop-title">拖入图片到此处</span><span class="upload-drop-subtitle">或点击选择图片，支持 PNG、JPG、WEBP，不能超过 8MB</span><input class="upload-drop-input" type="file" accept="image/png,image/jpeg,image/webp" @change="chooseFile" /><span v-if="bannerForm.imageKey" class="selected-file">已完成裁剪：{{ cropName }}</span></label><p class="form-help">手机轮播固定比例为 <b>16:7</b>，建议尺寸 1280×560 像素。自定义图片会先裁剪并上传，上传失败不能保存。</p><div class="dialog-grid"><label>轮播标题<input v-model="bannerForm.title" required maxlength="120" /></label><label>排序<input v-model.number="bannerForm.sort" type="number" min="0" step="1" /></label></div><label>点击后进入<select v-model="bannerForm.target" required><option value="/pages/index/index">小程序首页</option><option value="/pages/shop/list">商城首页</option><option value="/pages/prescriptions/list">处方服务</option></select></label><label class="dialog-check"><input v-model="bannerForm.active" type="checkbox" /> 在小程序首页启用</label><div class="dialog-actions"><button type="button" class="ghost-button" @click="bannerDialog = false">取消</button><button type="submit" class="primary-small" :disabled="uploadingImage">{{ uploadingImage ? '上传中' : '保存轮播' }}</button></div></form></div>

    <div v-if="cropDialog" class="dialog-backdrop crop-backdrop"><ImageCropper :source="cropImage" :ratio="16 / 7" :output-width="1280" :output-height="560" :file-name="cropName || '轮播图.jpg'" ratio-label="16:7" description="轮播图固定为 16:7，建议尺寸 1280×560 像素。" @confirm="handleBannerCrop" @cancel="cropDialog = false" /></div>
  </div>
</template>

<style scoped>
.content-manager { position: fixed; inset: 74px 0 0 252px; z-index: 45; overflow-y: auto; padding: 34px 44px 64px; background: #eef2f1; }
.article-list-toolbar { display: flex; align-items: center; gap: 12px; min-height: 44px; padding: 0 22px; border-bottom: 1px solid #e4ecea; background: #f4f9f7; color: #718783; font-size: 10px; }
.select-all-row { display: flex; align-items: center; gap: 7px; color: #567772; cursor: pointer; }.select-all-row input, .article-row-check { width: 16px; height: 16px; accent-color: #0f766e; }
.selected-count { color: #2e7c72; font-weight: 700; }.danger-small { min-height: 35px; padding: 0 12px; border-radius: 9px; background: #a85f58; color: #fff; font-size: 10px; }.page-size-select { min-width: 108px; }.content-pagination { display: flex; align-items: center; justify-content: flex-end; gap: 12px; padding: 12px 22px; border-top: 1px solid #e4ecea; color: #819894; font-size: 10px; }.content-pagination > div { display: flex; align-items: center; gap: 6px; }.content-pagination .icon-button { width: 28px; height: 28px; border: 1px solid #d6e3df; border-radius: 7px; background: #fff; color: #4d8a80; }.content-pagination .icon-button:disabled { opacity: .4; cursor: not-allowed; }
.content-manager-head { display: flex; align-items: flex-end; justify-content: space-between; max-width: 1480px; margin: 0 auto 20px; }.content-manager-head h2 { margin: 8px 0; color: #183b3b; font-family: "Noto Serif SC", serif; font-size: 26px; }.content-manager-head p { color: #77908e; font-size: 12px; }.content-manager-actions { display: flex; gap: 10px; }
.content-tabs { display: flex; gap: 8px; max-width: 1480px; margin: 0 auto 14px; }.content-tabs button { min-height: 36px; padding: 0 15px; border: 1px solid #d5e4df; border-radius: 9px; background: #f9fcfa; color: #66847e; font-size: 12px; }.content-tabs button.active { border-color: #0f766e; background: #0f766e; color: #fff; }
.content-toolbar { display: flex; align-items: center; gap: 10px; max-width: 1480px; margin: 0 auto 16px; }.content-toolbar .toolbar-search { width: 330px; margin: 0; }.content-count { margin-left: auto; color: #8da19f; font-size: 11px; }
.content-list { max-width: 1480px; margin: 0 auto; border: 1px solid #dce7e4; border-radius: 16px; background: #f9fcfa; }.content-row, .banner-row { display: flex; align-items: center; gap: 14px; min-height: 76px; padding: 12px 22px; border-bottom: 1px solid #e4ecea; }.content-row:last-child, .banner-row:last-child { border-bottom: 0; }.content-icon { display: grid; width: 42px; height: 42px; place-items: center; border-radius: 12px; background: #ddf1eb; color: #287c71; }.content-copy { display: flex; flex: 1; flex-direction: column; gap: 5px; }.content-copy b { color: #345552; font-size: 13px; }.content-copy small { color: #93a5a3; font-size: 10px; }.recommend-pill { padding: 4px 7px; border-radius: 6px; background: #fff0dc; color: #a96836; font-size: 9px; }.icon-danger { display: grid; width: 30px; height: 30px; place-items: center; border: 0; border-radius: 8px; background: transparent; color: #a85f58; }.icon-danger:hover { background: #fae8e5; }.content-empty { padding: 44px; color: #94a7a3; text-align: center; font-size: 12px; }.banner-preview { display: grid; width: 132px; height: 58px; overflow: hidden; place-items: center; border-radius: 8px; background: #eaf3f0; }.banner-preview img { width: 100%; height: 100%; object-fit: cover; }.content-dialog { width: min(720px, 100%); }.article-options { display: flex; gap: 24px; }.form-help { margin: 10px 0 0; color: #809995; font-size: 10px; line-height: 1.6; }.default-banner-options { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }.default-banner-option { display: flex; align-items: center; gap: 9px; padding: 9px; border: 1px solid #dbe8e4; border-radius: 9px; background: #f7fbf9; }.default-banner-option img { width: 115px; height: 50px; border-radius: 6px; object-fit: cover; }.custom-image-field input { min-height: auto; padding: 7px; }.selected-file { color: #287c71; font-size: 10px; }.crop-dialog { width: min(760px, 100%); padding: 24px; border: 1px solid #d5e4df; border-radius: 16px; background: #f9fcfa; box-shadow: 0 24px 60px rgba(13,52,53,.2); }.crop-stage { display: grid; width: 100%; aspect-ratio: 16 / 7; overflow: hidden; place-items: center; border: 2px solid #0f766e; border-radius: 12px; background: #173b3c; }.crop-stage img { width: 100%; height: 100%; object-fit: cover; }.crop-backdrop { z-index: 80; }
.crop-stage { position: relative; display: block; width: 100%; height: min(62vh, 520px); min-height: 300px; overflow: hidden; border: 2px solid #0f766e; border-radius: 12px; background: #263b3a; user-select: none; touch-action: none; }
.crop-source, .crop-viewport { position: absolute; }
.crop-source { pointer-events: none; }
.crop-viewport { overflow: visible; pointer-events: none; }
.crop-mask { position: absolute; z-index: 2; background: rgba(18, 28, 27, .58); pointer-events: none; }
.crop-selection { position: absolute; z-index: 3; box-sizing: border-box; border: 2px dashed #fff; outline: 1px solid rgba(15,118,110,.85); box-shadow: 0 0 0 9999px rgba(18,28,27,.02); cursor: move; pointer-events: auto; touch-action: none; }
.crop-handle { position: absolute; width: 16px; height: 16px; box-sizing: border-box; border: 2px solid #0f766e; border-radius: 4px; background: #fff; pointer-events: auto; touch-action: none; }
